def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    wall = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)

    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 2:
                out[r][c] = 2
            elif value == 4 and r + 1 < h:
                # Every 4 falls one row. A 4 two rows above the divider
                # also leaves a widening diagonal trail above its new cell.
                out[r + 1][c] = 4
                if wall is not None and r == wall - 2:
                    for k in range(1, wall):
                        rr = wall - 1 - k
                        if rr < 0:
                            break
                        for cc in (c - k, c + k):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
    return out
